var _ agent.TranscriptPreparer = (*CursorAgent)(nil)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNameCursor, NewCursorAgent)
}

// CursorAgent implements the Agent interface for Cursor.
//
//nolint:revive // CursorAgent is clearer than Agent in this context
type CursorAgent struct{}

// NewCursorAgent creates a new Cursor agent instance.
func NewCursorAgent() agent.Agent {
	return &CursorAgent{}
}

// Name returns the agent registry key.
func (c *CursorAgent) Name() types.AgentName {
	return agent.AgentNameCursor
}

// Type returns the agent type identifier.
func (c *CursorAgent) Type() types.AgentType {
	return agent.AgentTypeCursor
}

// Description returns a human-readable description.
func (c *CursorAgent) Description() string {
	return "Cursor - AI-powered code editor"
}

func (c *CursorAgent) IsPreview() bool { return true }

// DetectPresence checks if Cursor is configured in the repository.
func (c *CursorAgent) DetectPresence(ctx context.Context) (bool, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}

	cursorDir := filepath.Join(worktreeRoot, ".cursor")
	if _, err := os.Stat(cursorDir); err == nil {
		return true, nil
	}
	return false, nil
}

// GetSessionID extracts the session ID from hook input.
func (c *CursorAgent) GetSessionID(input *agent.HookInput) string {
	return input.SessionID
}

// ResolveSessionFile returns the path to a Cursor session file.
// Cursor IDE uses a nested layout: <dir>/<id>/<id>.jsonl
// Cursor CLI uses a flat layout: <dir>/<id>.jsonl
// We prefer nested if the file OR directory exists (the directory may be created
// before the file is flushed), otherwise fall back to flat.
func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	nestedDir := filepath.Join(sessionDir, agentSessionID)
	nested := filepath.Join(nestedDir, agentSessionID+".jsonl")
	if _, err := os.Stat(nested); err == nil {
		return nested
	}
	// IDE creates the directory before the transcript file — predict nested path.
	if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
		return nested
	}
	return filepath.Join(sessionDir, agentSessionID+".jsonl")
}

// ProtectedDirs returns directories that Cursor uses for config/state.
func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }

// GetSessionDir returns the directory where Cursor stores session transcripts.
func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
		return override, nil
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}

	projectDir := sanitizePathForCursor(repoPath)
	return filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts"), nil
}

// GetSessionBaseDir returns the base directory containing per-project session subdirectories.
// Unlike GetSessionDir, this does NOT use test overrides because the override
// points to a specific project dir, not the base containing all projects.
func (c *CursorAgent) GetSessionBaseDir() (string, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}
	return filepath.Join(homeDir, ".cursor", "projects"), nil
}

// ReadSession reads a session from Cursor's storage (JSONL transcript file).
// Note: ModifiedFiles is left empty because Cursor's transcript does not contain
// tool_use blocks for file detection. TranscriptAnalyzer extracts prompts and
// summaries; file detection relies on git status.
func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef)
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	return &agent.AgentSession{
		SessionID:  input.SessionID,
		AgentName:  c.Name(),
		SessionRef: input.SessionRef,
		StartTime:  time.Now(),
		NativeData: data,
	}, nil
}

// PrepareTranscript waits for Cursor's transcript file to be flushed to disk.
// Cursor writes transcripts asynchronously; during mid-turn commits the file
// may not yet contain data. This polls until the file exists and is non-empty,
// or until the timeout expires.
func (c *CursorAgent) PrepareTranscript(ctx context.Context, sessionRef string) error {
	const (
		maxWait      = 3 * time.Second
		pollInterval = 50 * time.Millisecond
	)

	logCtx := logging.WithComponent(ctx, "agent.cursor")

	deadline := time.Now().Add(maxWait)
	for time.Now().Before(deadline) {
		info, err := os.Stat(sessionRef)
		if err == nil {
			if info.Size() > 0 {
				logging.Debug(logCtx, "transcript file ready",
					slog.Int64("size", info.Size()),
				)
				return nil
			}
		} else if !os.IsNotExist(err) {
			return fmt.Errorf("failed to stat transcript %q: %w", sessionRef, err)
		}
		time.Sleep(pollInterval)
	}

	logging.Warn(logCtx, "transcript file not ready within timeout, proceeding",
		slog.Duration("timeout", maxWait),
		slog.String("path", sessionRef),
	)
	return nil
}

// WriteSession writes a session to Cursor's storage (JSONL transcript file).
func (c *CursorAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}

	if session.AgentName != "" && session.AgentName != c.Name() {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
	}

	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

// FormatResumeCommand returns an instruction to resume a Cursor session.
// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
func (c *CursorAgent) FormatResumeCommand(_ string) string {
	return "Open this project in Cursor to continue the session."
}

// sanitizePathForCursor converts a path to Cursor's project directory format.
var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)

func sanitizePathForCursor(path string) string {
	path = strings.TrimLeft(path, "/")
	return nonAlphanumericRegex.ReplaceAllString(path, "-")
}

// ChunkTranscript splits a JSONL transcript at line boundaries.
func (c *CursorAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
	}
	return chunks, nil
}

// ReassembleTranscript concatenates JSONL chunks with newlines.
func (c *CursorAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

package strategy

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// resolveTranscriptPath returns the current path to the session's transcript file.
// If the file exists at state.TranscriptPath, that path is returned immediately.
//
// If the file is missing (os.ErrNotExist), the function re-resolves the path
// using the agent's ResolveSessionFile method. This handles agents that relocate
// transcripts mid-session (e.g., Cursor CLI switching from a flat layout
// <dir>/<id>.jsonl to a nested layout <dir>/<id>/<id>.jsonl).
//
// On successful re-resolution, state.TranscriptPath is updated so that
// subsequent reads use the correct path without repeating the resolution.
func resolveTranscriptPath(state *SessionState) (string, error) {
	if state.TranscriptPath == "" {
		return "", errors.New("no transcript path in session state")
	}

	// Fast path: file exists at the stored location.
	if _, err := os.Stat(state.TranscriptPath); err == nil {
		return state.TranscriptPath, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		// Non-ENOENT error (permission denied, etc.) — return as-is.
		return "", fmt.Errorf("failed to access transcript: %w", err)
	}

	// File not found — attempt re-resolution via the agent.
	ag, agErr := agent.GetByAgentType(state.AgentType)
	if agErr != nil {
		return "", fmt.Errorf("transcript not found at %s: %w", state.TranscriptPath, os.ErrNotExist)
	}

	// Extract the session dir and agent session ID from the stored path.
	// Stored path format: <sessionDir>/<agentSessionID>.jsonl
	sessionDir := filepath.Dir(state.TranscriptPath)
	base := filepath.Base(state.TranscriptPath)
	agentSessionID := strings.TrimSuffix(base, filepath.Ext(base))

	resolved := ag.ResolveSessionFile(sessionDir, agentSessionID)
	if resolved == state.TranscriptPath {
		// Agent resolved to the same path — file genuinely doesn't exist.
		return "", fmt.Errorf("transcript not found at %s: %w", state.TranscriptPath, os.ErrNotExist)
	}

	// Check if the re-resolved path exists.
	if _, err := os.Stat(resolved); err != nil {
		return "", fmt.Errorf("transcript not found at %s (also tried %s): %w", state.TranscriptPath, resolved, os.ErrNotExist)
	}

	// Update state so subsequent reads use the correct path.
	state.TranscriptPath = resolved
	return resolved, nil
}

	// Prepare transcript before extraction (e.g., OpenCode `opencode export`).
	prepareTranscriptForState(ctx, state)

	return s.extractModifiedFilesFromLiveTranscript(ctx, state, state.CheckpointTranscriptStart)
}

// hasNewTranscriptWork checks if the agent has done work since the last condensation.
// Uses agent-delegated GetTranscriptPosition() — does NOT do file extraction.
// All call sites that need "has the agent done new work?" should use this.
//
// Returns false if: no transcript path, unknown agent type, agent doesn't implement
// TranscriptAnalyzer, or GetTranscriptPosition fails. This is intentional fail-safe
// behavior: callers treat false as "no new work detected", which conservatively
// skips condensation on errors.
func (s *ManualCommitStrategy) hasNewTranscriptWork(ctx context.Context, state *SessionState) bool {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	if state.TranscriptPath == "" || state.AgentType == "" {
		return false
	}

	// Re-resolve transcript path — handles agents that relocate transcripts mid-session.
	if _, resolveErr := resolveTranscriptPath(state); resolveErr != nil {
		logging.Debug(logCtx, "hasNewTranscriptWork: transcript path resolution failed",
			slog.String("session_id", state.SessionID),
			slog.Any("error", resolveErr),
		)
		return false
	}

	ag, err := agent.GetByAgentType(state.AgentType)
	if err != nil {
		return false
	}

	// Ensure transcript file is up-to-date (OpenCode creates/refreshes it via `opencode export`).
	// Only wait for flush when the session is active — for idle/ended sessions the
	// transcript is already fully flushed (the Stop hook completed the flush).
	if state.Phase.IsActive() {
		if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
			if prepErr := preparer.PrepareTranscript(ctx, state.TranscriptPath); prepErr != nil {
				logging.Debug(logCtx, "prepare transcript failed",
					slog.String("session_id", state.SessionID),
					slog.String("agent_type", string(state.AgentType)),
					slog.String("transcript_path", state.TranscriptPath),
					slog.Any("error", prepErr),
				)
			}
		}
	}
	analyzer, ok := agent.AsTranscriptAnalyzer(ag)
	if !ok {
		return false
	}

	currentPos, err := analyzer.GetTranscriptPosition(state.TranscriptPath)
	if err != nil {
		logging.Debug(logCtx, "hasNewTranscriptWork: GetTranscriptPosition failed",
			slog.String("session_id", state.SessionID),
			slog.String("transcript_path", state.TranscriptPath),
			slog.Any("error", err),
		)
		return false
	}

	if currentPos <= state.CheckpointTranscriptStart {
		logging.Debug(logCtx, "hasNewTranscriptWork: no new content",
			slog.String("session_id", state.SessionID),
			slog.Int("current_pos", currentPos),
			slog.Int("start_offset", state.CheckpointTranscriptStart),
		)
		return false
	}

	return true
}

// extractModifiedFilesFromLiveTranscript extracts modified files from the live transcript
// (including subagent transcripts) starting from the given offset, and normalizes them
// to repo-relative paths. Returns the normalized file list.
//
// Callers must ensure the transcript is prepared (e.g., via prepareTranscriptForState
// or hasNewTranscriptWork) before calling this function.
func (s *ManualCommitStrategy) extractModifiedFilesFromLiveTranscript(ctx context.Context, state *SessionState, offset int) []string {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	if state.TranscriptPath == "" || state.AgentType == "" {
		return nil
	}

	// Re-resolve transcript path — handles agents that relocate transcripts mid-session.
	if _, resolveErr := resolveTranscriptPath(state); resolveErr != nil {
		logging.Debug(logCtx, "extractModifiedFilesFromLiveTranscript: transcript path resolution failed",
			slog.String("session_id", state.SessionID),
			slog.Any("error", resolveErr),
		)
		return nil
	}

