35	// PromptPattern returns a regex matching Cursor's ready-state prompt markers.
36	// Cursor has used multiple startup/completion markers across releases.
37	func (a *CursorCLI) PromptPattern() string {
38		return `(/ commands|Plan, search, build anything|Add a follow-up)`
39	}
40	
41	func (a *CursorCLI) IsTransientError(out Output, err error) bool {
42		if err == nil {
43			return false
44		}
45		if errors.Is(err, context.DeadlineExceeded) {
46			return true
47		}
48		combined := out.Stdout + out.Stderr
49		for _, p := range []string{
50			"overloaded",
51			"rate limit",
52			"429",
53			"503",
54			"529",
55			"ECONNRESET",
56			"ETIMEDOUT",
57			"server error",
58			"Internal Server Error",
59		} {
60			if strings.Contains(combined, p) {
61				return true
62			}
63		}
64		return false
65	}
66	
67	func (a *CursorCLI) Bootstrap() error {
68		// The Cursor CLI authenticates via CURSOR_API_KEY env var or OAuth.
69		// On CI, ensure CURSOR_API_KEY is set. Locally, OAuth/keychain works.
70		if os.Getenv("CI") != "" && os.Getenv("CURSOR_API_KEY") == "" {
