110		// (beforeSubmitPrompt and stop don't fire in headless -p mode).
111		s, err := a.startInteractiveSession(dir)
112		if err != nil {
113			return Output{Command: displayCmd, ExitCode: -1},
114				fmt.Errorf("start interactive session: %w", err)
115		}
116		defer s.Close()
117	
118		// Wait for trust dialog and accept it.
119		if err := a.acceptTrustDialogIfNeeded(s); err != nil {
120			return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1}, err
121		}
122	
123		// Wait for the TUI to be ready.
124		if _, err := s.WaitFor(a.PromptPattern(), 30*time.Second); err != nil {
125			return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
126				fmt.Errorf("waiting for startup prompt: %w", err)
127		}
128	
129		// Send the prompt.
130		if err := s.Send(prompt); err != nil {
131			return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
132				fmt.Errorf("sending prompt: %w", err)
133		}
