136		// finishes processing. We cannot reuse PromptPattern() ("/ commands")
137		// because that text is always visible in the status bar — even during
138		// the "Thinking" phase — causing WaitFor to settle prematurely when the
139		// model takes >2s to start producing visible output.
140		content, waitErr := s.WaitFor(`Add a follow-up`, timeout)
